CREATE TEMP TABLE t1(a,b); INSERT INTO t1 VALUES('a','b'); CREATE TEMP TRIGGER tr1 AFTER INSERT ON t1 BEGIN SELECT 1; END; ATTACH ':memory:' AS aux; CREATE TABLE aux.t3(a,b); INSERT INTO aux.t3 VALUES('a','b'); CREATE TRIGGER aux.tr1 BEFORE INSERT ON t3 BEGIN SELECT 1; END; CREATE TRIGGER aux.tr2 AFTER INSERT ON t3 BEGIN SELECT 1; END; CREATE TRIGGER aux.tr3 AFTER INSERT ON t3 BEGIN SELECT 1; END; DROP TRIGGER main.tr1; INSERT INTO observed(scope,name) SELECT 'main',name FROM main.sqlite_schema WHERE type='trigger'; INSERT INTO observed(scope,name) SELECT 'temp',name FROM sqlite_temp_schema WHERE type='trigger'; INSERT INTO observed(scope,name) SELECT 'aux',name FROM aux.sqlite_schema WHERE type='trigger';